const fileUrl = 'file://' + encodeURI('~/Library/Application Support/Slate/evals/runs/20261001-l1b-claude-code/negative-css-video-element/claude-code/work/site/index.html');
const tab = await openTab(fileUrl);
const rows = [];
try {
  for (const w of [320, 375, 390, 430, 768, 1000, 1280]) {
    await tab.setViewportSize({ width: w, height: 800 });
    const m = await tab.evaluate(() => {
      const de = document.documentElement;
      const hero = document.querySelector('.hero');
      const video = document.querySelector('.hero-video');
      const hs = getComputedStyle(hero);
      const vs = getComputedStyle(video);
      const hr = hero.getBoundingClientRect();
      const vr = video.getBoundingClientRect();
      const heroContentRight = hr.right - parseFloat(hs.paddingRight);
      const sticksOut = [...document.querySelectorAll('body *')]
        .filter((el) => el.getBoundingClientRect().right > de.clientWidth + 0.5)
        .map((el) => `${el.tagName.toLowerCase()}${el.className ? '.' + el.className : ''} (right ${Math.round(el.getBoundingClientRect().right)})`);
      return {
        viewport: window.innerWidth,
        docClient: de.clientWidth,
        docScroll: de.scrollWidth,
        heroContentW: Math.round(heroContentRight - (hr.left + parseFloat(hs.paddingLeft))),
        videoW: Math.round(vr.width),
        videoH: Math.round(vr.height),
        videoOverflowsHero: vr.right > heroContentRight + 0.5,
        videoCss: `width:${vs.width} max-width:${vs.maxWidth}`,
        sticksOut,
      };
    });
    rows.push(m);
  }
} finally {
  await closeTab(tab);
}
for (const r of rows) console.log(JSON.stringify(r));

