// Loads index.html in same-origin iframes of fixed widths (each iframe's width is
// its document's viewport) and measures the hero video against its container.
await openTab('http://127.0.0.1:8731/index.html');
let rows;
try {
  rows = await page.evaluate(async () => {
    document.body.innerHTML = '';
    const out = [];
    for (const w of [320, 375, 390, 430, 768, 1000, 1280]) {
      const f = document.createElement('iframe');
      f.style.cssText = `width:${w}px;height:800px;border:0;display:block`;
      const loaded = new Promise((r) => f.addEventListener('load', r, { once: true }));
      f.src = '/index.html?w=' + w;
      document.body.appendChild(f);
      await loaded;
      const doc = f.contentDocument;
      const win = f.contentWindow;
      const de = doc.documentElement;
      const hero = doc.querySelector('.hero');
      const video = doc.querySelector('.hero-video');
      const hs = win.getComputedStyle(hero);
      const vs = win.getComputedStyle(video);
      const hr = hero.getBoundingClientRect();
      const vr = video.getBoundingClientRect();
      const heroContentLeft = hr.left + parseFloat(hs.paddingLeft);
      const heroContentRight = hr.right - parseFloat(hs.paddingRight);
      const sticksOut = [...doc.querySelectorAll('body *')]
        .filter((el) => el.getBoundingClientRect().right > de.clientWidth + 0.5)
        .map((el) => `${el.tagName.toLowerCase()}${el.className ? '.' + el.className : ''} (right ${Math.round(el.getBoundingClientRect().right)})`);
      out.push({
        viewport: win.innerWidth,
        docClient: de.clientWidth,
        docScroll: de.scrollWidth,
        heroContentW: Math.round(heroContentRight - heroContentLeft),
        videoW: Math.round(vr.width),
        videoH: Math.round(vr.height),
        videoOverflowsHero: vr.right > heroContentRight + 0.5,
        videoCss: `width:${vs.width} max-width:${vs.maxWidth}`,
        sticksOut,
      });
      f.remove();
    }
    return out;
  });
} finally {
  await closeTab(page);
}
for (const r of rows) console.log(JSON.stringify(r));

